//! Built-in provider catalog: registers every bundled third-party provider
//! through the same `register_provider` API user extensions use, so Phi
//! ships batteries-included without the core registry knowing anything
//! beyond its first-party providers.
//!
//! The data (`catalog.json`) is generated by `cargo xtask generate-models`
//! from models.dev, filtered to providers a Phi backend can actually drive
//! with plain API-key auth. A user extension that registers a provider with
//! the same name overrides the bundled entry (last write wins), which is how
//! you point a bundled provider at a proxy or inject an inline key.

use std::sync::OnceLock;

use anyhow::Result;
use phi_ext::{Extension, ExtensionHost, ExtensionManifest, ProviderConfig};

static CATALOG_JSON: &str = include_str!("catalog.json");

/// The bundled provider configs, parsed once. Exposed so listing surfaces
/// (`--list-models`, `/model` completion) can see bundled models without
/// booting an extension runtime.
pub fn provider_configs() -> &'static [ProviderConfig] {
    static PARSED: OnceLock<Vec<ProviderConfig>> = OnceLock::new();
    PARSED.get_or_init(|| {
        serde_json::from_str(CATALOG_JSON)
            .unwrap_or_else(|e| panic!("embedded catalog.json failed to parse: {e}"))
    })
}

/// Qualified `provider/model-id` names for every bundled model.
pub fn model_names() -> impl Iterator<Item = String> {
    provider_configs()
        .iter()
        .flat_map(|p| p.models.iter().map(|m| format!("{}/{}", p.name, m.id)))
}

/// The built-in catalog extension.
pub struct CatalogExtension;

impl Extension for CatalogExtension {
    fn manifest(&self) -> ExtensionManifest {
        ExtensionManifest {
            id: "phi:catalog".to_string(),
            name: "Phi Provider Catalog".to_string(),
            version: "0.1.0".to_string(),
            description: "Bundled third-party providers (generated from models.dev)".to_string(),
        }
    }

    fn register(&self, host: &mut dyn ExtensionHost) -> Result<()> {
        for config in provider_configs() {
            host.register_provider(config.clone())?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_parses_and_is_nonempty() {
        let configs = provider_configs();
        assert!(configs.len() > 50, "catalog looks truncated");
        for p in configs {
            assert!(
                p.base_url.is_some(),
                "provider '{}' has no base_url",
                p.name
            );
            assert!(!p.models.is_empty(), "provider '{}' has no models", p.name);
            assert!(
                p.api_key.is_none(),
                "provider '{}' ships a hardcoded api_key",
                p.name
            );
        }
    }

    #[test]
    fn catalog_apis_are_drivable() {
        // Every bundled entry must speak an API Phi implements; anything
        // else belongs to the xtask skip list, not the catalog.
        let drivable = [
            "anthropic-messages",
            "openai-responses",
            "openai-completions",
        ];
        for p in provider_configs() {
            let api = p.api.as_deref().unwrap_or("openai-completions");
            assert!(
                drivable.contains(&api),
                "provider '{}' has undrivable api '{api}'",
                p.name
            );
        }
    }

    #[test]
    fn catalog_carries_full_fidelity() {
        // The regression that motivated the catalog: neuralwatt/glm-5.2 with
        // its override limits, cost, and thinking levels intact.
        let nw = provider_configs()
            .iter()
            .find(|p| p.name == "neuralwatt")
            .expect("neuralwatt bundled");
        let glm = nw
            .models
            .iter()
            .find(|m| m.id == "glm-5.2")
            .expect("glm-5.2");
        assert_eq!((glm.context_window, glm.max_tokens), (200_000, 65_536));
        assert!(glm.cost.is_some());
        assert!(glm.thinking_levels.is_some());
    }
}
